const DOC_TYPES = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  'application/vnd.ms-excel',
  'text/csv',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'application/msword',
];
const MIN_IMAGE_KB = 40; // signatures/logos are below this; covers/flyers above

function sizeKB(b) {
  const m = (b.fileSize || '').toString().match(/([\d.]+)\s*(kB|MB|B)\b/i);
  if (!m) return Infinity;
  const n = parseFloat(m[1]);
  const u = m[2].toUpperCase();
  return u === 'MB' ? n * 1024 : u === 'B' ? n / 1024 : n;
}

const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  for (const key of Object.keys(bin)) {
    const b = bin[key];
    const mime = (b.mimeType || '').toLowerCase();
    const isImage = mime.startsWith('image/');

    if (isImage && sizeKB(b) < MIN_IMAGE_KB) continue;   // drop only small images (signatures)
    if (!DOC_TYPES.includes(mime) && !isImage) continue; // ignore non-doc, non-image files

    out.push({
      json: { message_id: item.json.id, thread_id: item.json.threadId, filename: b.fileName || key },
      binary: { data: b },
    });
  }
}
return out;

// Group parsed markdown per email into a single attachments_text string.
const byEmail = {};
for (const item of $input.all()) {
  const id = item.json.message_id;
  const md = item.json.attachment_markdown || '';
  if (!byEmail[id]) byEmail[id] = [];
  if (md) byEmail[id].push(md);
}
return Object.keys(byEmail).map((id) => ({
  json: { message_id: id, attachments_text: byEmail[id].join('\n\n---\n\n') },
}));

// Explode each relevant AI result into one row per catalog item, mapped to the REAL
// catalog_lines columns, and decide DETERMINISTICALLY (no AI) whether each item is a
// new line or an update to an existing one. Extras -> extra (jsonb).
//
// Matching cascade, in order, against lines NOT yet sent to Hermes:
//   1. EAN        — digits only, leading zeros ignored (the same product arrives as
//                   "0093624872443" and as "093624872443")
//   2. catalogue number — punctuation/spacing ignored
// Identifiers ONLY: artist/title/format are never used to match, because the same
// artist + title + format is routinely several different SKUs. An item carrying
// neither an EAN nor a catalogue number therefore always becomes a new line, to be
// merged by hand. The catalogue-number tier fires only when EXACTLY ONE candidate
// matches, and never across a conflicting barcode: two lines sharing a catalogue
// number but carrying different EANs are different products. Anything ambiguous
// becomes a new line flagged for review rather than a guess.
//
// Lines already sent to Hermes are frozen — Hermes is insert-only, so an update
// cannot be pushed there. A follow-up for one of those leaves the data untouched and
// records a note instead of disappearing silently.

function toCatalogCode(ean) {
  if (ean === null || ean === undefined) return null;
  const s = String(ean).replace(/\D/g, '');
  if (!s) return null;
  const trimmed = s.slice(0, -1).replace(/^0+/, '');
  return trimmed || null;
}

// Hard guarantee (never trust the model): neither artist nor title may start
// with "THE". Strip a leading "THE " (case-insensitive) + surrounding spaces.
function dropThe(s) {
  if (typeof s !== 'string') return s;
  let t = s;
  while (t[0] === ' ') t = t.slice(1);
  if (t.slice(0, 4).toUpperCase() === 'THE ') { t = t.slice(4); while (t[0] === ' ') t = t.slice(1); }
  return t;
}

// Title must carry the RELEASE NAME ONLY. Strip parenthesised/bracketed groups
// that describe the edition/packaging (and a trailing " - <colour/format>" tail),
// keeping genuine parts of the work's name. What is removed is preserved in
// extra.title_variant so nothing is lost.
const VARIANT_RE = /\b(VINYL|LP|CD|MC|DIGI|DIGIPAK|DIGIPACK|LTD|LIMITED|EXCLUSIVE|INDIE|RSD|SIGNED|PICTURE|DISC|DIE-CUT|GATEFOLD|T-SHIRT|PATCH|BOXSET|BOX|DELUXE|EDITION|REISSUE|BLACK|WHITE|RED|GREEN|BLUE|YELLOW|GOLD|SILVER|CLEAR|ORANGE|PURPLE|PINK|GREY|GRAY|MARBLE|SPLATTER|GLITTER|TRANSPARENT|INKSPOT|GLOW|SLUDGE|OPAQUE|CRYSTAL|SOFTPAK|JEWEL|AMARAY|LIGHT)\b/;
function cleanTitle(s) {
  if (typeof s !== 'string') return { title: s, removed: [] };
  const removed = [];
  let t = s.replace(/\s*[\(\[]([^()\[\]]*)[\)\]]/g, function (m, inner) {
    if (VARIANT_RE.test(inner.toUpperCase())) { removed.push(inner.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s+[-–]\s+([^-–]+)$/, function (m, seg) {
    const words = seg.trim().toUpperCase().split(/[\s,\/&+]+/).filter(Boolean);
    if (words.length && words.every(function (w) { return VARIANT_RE.test(w) || /^[0-9]+$/.test(w); })) { removed.push(seg.trim()); return ''; }
    return m;
  });
  t = t.replace(/\s{2,}/g, ' ').replace(/[\s,;:\-–]+$/, '').trim();
  return { title: t, removed: removed };
}
// Artist and title are always upper-case (client rule).
function up(s) { return typeof s === 'string' ? s.toUpperCase() : s; }

// --- matching keys ---------------------------------------------------------
function keyEan(v) {
  const d = String(v === null || v === undefined ? '' : v).replace(/\D/g, '').replace(/^0+/, '');
  return d || '';
}
function keyCat(v) {
  return String(v === null || v === undefined ? '' : v).toUpperCase().replace(/[^A-Z0-9]/g, '');
}
// Returns {line, via} on a confident match, {ambiguous, count} when more than one
// candidate fits (never guess), or null when nothing matches.
function findMatch(pool, used, row) {
  const ean = keyEan(row.ean);
  const cat = keyCat(row.catalogue_no);
  const free = pool.filter(function (c) { return !used.has(c.id); });
  // A candidate carrying a DIFFERENT barcode is a different product, full stop.
  const eanOk = function (c) { const ce = keyEan(c.ean); return !ce || !ean || ce === ean; };

  const tiers = [];
  if (ean) tiers.push(['ean', free.filter(function (c) { return keyEan(c.ean) === ean; })]);
  if (cat) tiers.push(['catalogue_no', free.filter(function (c) { return keyCat(c.catalogue_no) === cat && eanOk(c); })]);

  for (const tier of tiers) {
    if (tier[1].length === 1) return { line: tier[1][0], via: tier[0] };
    if (tier[1].length > 1) return { ambiguous: tier[0], count: tier[1].length };
  }
  return null;
}

// --- small helpers ---------------------------------------------------------
function isBlank(v) { return v === null || v === undefined || v === ''; }
function stripBlank(obj) {
  const out = {};
  for (const k of Object.keys(obj)) if (!isBlank(obj[k])) out[k] = obj[k];
  return out;
}
function appendNote(existing, add) {
  const cur = String(existing === null || existing === undefined ? '' : existing).trim();
  if (!add) return cur || null;
  if (!cur) return add;
  if (cur.indexOf(add) !== -1) return cur;   // already recorded — don't repeat it
  return cur + '\n' + add;
}

// "We are not sure" must NEVER become an exclusion. A "WW ex US" release IS
// sellable in Slovenia; excluding it costs the client real business, while
// keeping it costs one review. Only a definite restriction excludes.
const UNSURE_RE = /\b(UNCLEAR|UNCERTAIN|AMBIGUOUS|POSSIBLY|POTENTIALLY|PRESUMABLY|APPARENTLY|UNKNOWN|UNSPECIFIED|NOT SPECIFIED|NOT CLEAR|CANNOT BE DETERMINED)\b/i;

// Fields worth reporting when a follow-up lands on a line that is already in Hermes.
const WATCHED = ['artist', 'title', 'format', 'unit', 'ean', 'catalogue_no', 'release_date', 'label', 'cop', 'ppd', 'rock_bottom', 'price_original', 'currency', 'calculation_group'];

const MANDATORY = $('MandatoryFields').all().map(function (i) { return i.json.field_name; }).filter(Boolean);

const allLines = $('Catalog Lines (matching)').all().map(function (i) { return i.json; });
const openPool = allLines.filter(function (l) { return !l.sent_at; });   // updatable
const sentPool = allLines.filter(function (l) { return !!l.sent_at; });  // frozen in Hermes
const usedOpen = new Set();
const usedSent = new Set();
const createdEans = new Set();

const rows = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  let result = inputs[i].json;
  result = result.output ?? result.message?.content ?? result.content ?? result;
  if (typeof result === 'string') { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) { continue; } }
  if (!result || result.is_catalog_relevant === false) continue;

  // One source per run, so fall back to the single item when n8n cannot trace
  // the pairing through the merge/agent nodes.
  let src = {};
  try { src = $('Set Fields').itemMatching(i).json; }
  catch (e) { try { src = $('Set Fields').first().json; } catch (e2) {} }
  const stamp = String(src.date || '').slice(0, 10) || new Date().toISOString().slice(0, 10);

  for (const item of (result.items ?? [])) {
    const _t = cleanTitle(dropThe(item.title ?? null));

    // Territory guard — see UNSURE_RE above.
    let excluded = item.excluded === true;
    let exclusionReason = item.exclusion_reason ?? null;
    let reviewNote = null;
    if (excluded && exclusionReason && UNSURE_RE.test(exclusionReason)) {
      excluded = false;
      reviewNote = 'Kept in the catalog: the exclusion reason was not definite ("' + exclusionReason + '"). Please confirm the territory.';
      exclusionReason = null;
    }

    const fields = {
      status: excluded ? 'excluded' : 'in_progress',
      label: result.label ?? null,
      catalog: (result.label === 'Matrix Music' || result.label === 'I-DI music' || result.label === 'Pias Recordings') ? 'other' : 'main',
      thread_id: src.thread_id ?? null,
      artist: up(dropThe(item.artist ?? null)),
      title: up(_t.title),
      format: item.format ?? null,
      genre: item.genre ?? null,
      unit: item.unit ?? null,
      ean: item.ean ?? null,
      code: toCatalogCode(item.ean),
      catalogue_no: item.catalogue_no ?? null,
      release_date: item.release_date ?? null,
      price_original: item.price ?? null,
      currency: item.currency ?? null,
      cop: item.cop ?? null,
      ppd: (function(a,b){a=a!=null?String(a).replace('.',','):null;b=b!=null?String(b).replace('.',','):null;return a&&b?a+'/'+b:(a||b||null);})(item.ppd_eur, item.rock_bottom),
      rock_bottom: item.rock_bottom ?? null,
      our_price: null,
      calculation_group: item.calculation_group ?? '1',
      supplier_code: result.label === 'Matrix Music' ? '54' : (result.label === 'I-DI music' || result.label === 'Pias Recordings') ? null : '149',
      confidence: item.item_confidence ?? result.overall_confidence ?? null,
      notes: item.item_notes ?? null,
    };
    const newExtra = stripBlank({
      artist_raw: item.artist_raw ?? null,
      title_variant: _t.removed.length ? _t.removed.join(' / ') : null,
      exclusion_reason: exclusionReason,
      review_note: reviewNote,
      needs_review: (result.needs_review || reviewNote) ? true : null,
      source_message_id: src.message_id ?? null,
    });

    let match = findMatch(openPool, usedOpen, fields);
    let ambiguousVia = null;
    if (match && match.ambiguous) { ambiguousVia = match.ambiguous; match = null; }

    // --- already in Hermes: report, don't touch ----------------------------
    if (!match) {
      const frozen = findMatch(sentPool, usedSent, fields);
      if (frozen && frozen.line) {
        const line = frozen.line;
        usedSent.add(line.id);
        const changes = [];
        for (const k of WATCHED) {
          if (isBlank(fields[k])) continue;
          const ov = line[k];
          if (String(isBlank(ov) ? '' : ov) !== String(fields[k])) {
            changes.push(k + ': ' + (isBlank(ov) ? '—' : ov) + ' -> ' + fields[k]);
          }
        }
        // Nothing new (e.g. the same email re-processed) -> no note, no write.
        if (!changes.length) continue;
        const note = '[' + stamp + '] Follow-up arrived after this line was sent to Hermes, so it was NOT applied automatically: ' + changes.join('; ');
        rows.push({ json: {
          action: 'update',
          match_line_id: line.id,
          notes: appendNote(line.notes, note),
          extra: Object.assign({}, line.extra || {}, { late_update: { at: stamp, via: frozen.via, changes: changes } }),
        } });
        continue;
      }
    }

    // --- update an open line -----------------------------------------------
    if (match && match.line) {
      const line = match.line;
      usedOpen.add(line.id);
      const patch = stripBlank(fields);   // only what THIS source actually states
      delete patch.our_price;             // always null here; the client fills it by hand
      delete patch.catalog;               // a manual move between Main/Other must stick

      // Never silently un-approve something a human already signed off.
      let approvedNote = null;
      if (line.status === 'approved') {
        delete patch.status;
        if (excluded) {
          approvedNote = '[' + stamp + '] This source marks the release as excluded (' + (exclusionReason || 'no reason given') + ') but the line is already approved — left approved, please review.';
        }
      }

      const merged = appendNote(line.notes, [fields.notes, reviewNote, approvedNote].filter(Boolean).join(' '));
      if (isBlank(merged)) delete patch.notes; else patch.notes = merged;

      const mergedExtra = Object.assign({}, line.extra || {}, newExtra);
      // Back in the catalog -> drop any stale exclusion reason.
      if (!excluded) mergedExtra.exclusion_reason = null;
      patch.extra = mergedExtra;

      // Recompute against the MERGED line, not just this source: a follow-up that
      // supplies the missing EAN should clear "ean" from missing_fields.
      const mergedRow = Object.assign({}, line, patch);
      patch.missing_fields = MANDATORY.filter(function (f) { return isBlank(mergedRow[f]); });

      rows.push({ json: Object.assign({ action: 'update', match_line_id: line.id }, patch) });
      continue;
    }

    // --- new line ------------------------------------------------------------
    const ek = keyEan(fields.ean);
    if (ek && createdEans.has(ek)) continue;   // same barcode listed twice in one source
    if (ek) createdEans.add(ek);

    const row = Object.assign({}, fields);
    row.extra = Object.assign({}, newExtra);
    if (ambiguousVia) {
      row.extra.review_note = appendNote(row.extra.review_note, 'Several open lines matched on ' + ambiguousVia + ' — created a new line instead of guessing which one to update.');
      row.extra.needs_review = true;
    }
    row.notes = appendNote(fields.notes, reviewNote);
    row.missing_fields = MANDATORY.filter(function (f) { return isBlank(row[f]); });
    rows.push({ json: Object.assign({ action: 'create', match_line_id: null }, row) });
  }
}
return rows;

