// One raw_entries row per processed source (audit + dedupe link),
// mapped to the REAL raw_entries columns. Full payload kept in `extracted` (jsonb).
const out = [];
const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  let result = inputs[i].json;
  result = result.output ?? result.message?.content ?? result.content ?? result;
  if (typeof result === "string") { const a = result.indexOf('{'), b = result.lastIndexOf('}'); try { result = JSON.parse(a >= 0 && b > a ? result.slice(a, b + 1) : result); } catch (e) {} }

  // One source per run, so fall back to the single item when n8n cannot trace
  // the pairing through the merge/agent nodes.
  let src = {};
  try { src = $("Set Fields").itemMatching(i).json; }
  catch (e) { try { src = $("Set Fields").first().json; } catch (e2) {} }

  out.push({ json: {
    received_at: src.date ?? null,
    sender: src.from ?? null,
    label: result?.label ?? null,
    subject: src.subject ?? null,
    source_email_id: src.message_id ?? null,
    ean: result?.items?.[0]?.ean ?? null,
    confidence: result?.overall_confidence ?? null,
    status: "new",
    extracted: {
      result: result ?? null,
      source_body: src.body ?? null,
      source_attachments: src.attachments_text ?? null,
    },
  } });
}
return out;
